func computeBuildProfile(targets []BuildTargetReport, cfg *Config, targetMap map[string]*TargetConfig) *BuildProfile {
	durationByName := map[string]int64{}
	successful := map[string]bool{}
	hasBuilt := false
	for _, t := range targets {
		if t.Status == "built" || t.Status == "cached" {
			successful[t.Name] = true
			if t.Status == "cached" {
				durationByName[t.Name] = 0
