				}
			}
		}
	}
	if len(successful) == 0 || !hasBuilt {
		return &BuildProfile{CriticalPath: []string{}, CriticalPathMS: 0}
	}
	deps := map[string][]string{}
	for name := range successful {
		t, ok := targetMap[name]
		if !ok {
			continue
		}
		for _, dep := range uniqueStrings(t.Dependencies) {
			if successful[dep] {
				deps[name] = append(deps[name], dep)
			}
		}
		sort.Strings(deps[name])
	}
	order := []string{}
	seen := map[string]bool{}
	var visit func(string)
	visit = func(n string) {
