		seen[n] = true
		for _, dep := range deps[n] {
			visit(dep)
		}
		order = append(order, n)
	}
	for _, t := range cfg.Targets {
		if successful[t.Name] {
			visit(t.Name)
		}
	}
	dp := map[string]buildPath{}
	for _, name := range order {
		best := buildPath{names: []string{name}, weight: durationByName[name]}
		for _, dep := range deps[name] {
			cand := buildPath{
				names:  append(append([]string{}, dp[dep].names...), name),
				weight: dp[dep].weight + durationByName[name],
			}
			if betterBuildPath(cand, best) {
				best = cand
			}
		}
		dp[name] = best
	}
	var best buildPath
	for _, name := range order {
		p := dp[name]
		if best.names == nil || betterBuildPath(p, best) {
			best = p
		}
	}
	return &BuildProfile{CriticalPath: best.names, CriticalPathMS: best.weight}
}

func betterBuildPath(a, b buildPath) bool {
	if a.weight != b.weight {
		return a.weight > b.weight
	}
	if len(a.names) != len(b.names) {
		return len(a.names) > len(b.names)
	}
	for i := 0; i < len(a.names); i++ {
		if a.names[i] != b.names[i] {
			return a.names[i] < b.names[i]
		}
	}
	return false
}
